// Fully secure Express application with environment variables for all configuration

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// Validate required environment variables
const requiredEnvVars = ['PORT'];
const missingEnvVars = requiredEnvVars.filter(varName => !process.env[varName]);

if (missingEnvVars.length > 0) {
  console.error('Missing required environment variables:', missingEnvVars.join(', '));
  console.error('Please check your .env file or environment configuration');
  process.exit(1);
}

const app = express();

// Parse numeric environment variables with defaults
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000; // 15 minutes default
const RATE_LIMIT_MAX = parseInt(process.env.RATE_LIMIT_MAX) || 100; // 100 requests default
const PORT = parseInt(process.env.PORT);
const BODY_SIZE_LIMIT = process.env.BODY_SIZE_LIMIT || '10kb';

// Security middleware - Helmet with CSP
const helmetConfig = {
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
};

// Allow CSP to be disabled in development if needed
if (process.env.DISABLE_CSP === 'true') {
  delete helmetConfig.contentSecurityPolicy;
}

app.use(helmet(helmetConfig));

// CORS configuration from environment variables
const corsOptions = {
  origin: process.env.CORS_ORIGINS 
    ? process.env.CORS_ORIGINS.split(',').map(origin => origin.trim())
    : (process.env.NODE_ENV === 'production' 
        ? []  // Empty array means no CORS in production unless explicitly configured
        : ['http://localhost:3000', 'http://localhost:3001']),
  credentials: process.env.CORS_CREDENTIALS === 'true' || false,
  methods: process.env.CORS_METHODS || 'GET,HEAD,PUT,PATCH,POST,DELETE',
  allowedHeaders: process.env.CORS_ALLOWED_HEADERS 
    ? process.env.CORS_ALLOWED_HEADERS.split(',')
    : ['Content-Type', 'Authorization'],
};

app.use(cors(corsOptions));

// Rate limiting from environment variables
const limiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX,
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: process.env.DISABLE_RATE_LIMIT === 'true' ? () => true : undefined,
});

app.use(limiter);

// Body parsing with size limits from environment variables
app.use(express.json({ limit: BODY_SIZE_LIMIT }));
app.use(express.urlencoded({ 
  extended: process.env.URLENCODED_EXTENDED !== 'false', // true by default
  limit: BODY_SIZE_LIMIT 
}));

// Routes
app.get('/health', (req, res) => {
  // Minimal health check response
  const healthData = {
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development',
    version: process.env.APP_VERSION || '1.0.0',
  };

  // Only include additional info if not in production
  if (process.env.NODE_ENV !== 'production') {
    healthData.uptime = process.uptime();
    healthData.memory = process.memoryUsage();
  }

  res.json(healthData);
});

app.get('/users', (req, res) => {
  // In a real application, this would come from a database
  // Demo data with configurable count
  const userCount = parseInt(process.env.DEMO_USER_COUNT) || 2;
  const users = [];

  for (let i = 1; i <= userCount; i++) {
    users.push({
      id: i,
      name: `User ${i}`,
      email: `user${i}@${process.env.EMAIL_DOMAIN || 'example.com'}`,
    });
  }

  res.json(users);
});

// Additional configurable endpoint
app.get('/config', (req, res) => {
  // Only allow in non-production environments
  if (process.env.NODE_ENV === 'production' && process.env.ALLOW_CONFIG_ENDPOINT !== 'true') {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const safeConfig = {
    environment: process.env.NODE_ENV,
    port: PORT,
    rateLimit: {
      windowMs: RATE_LIMIT_WINDOW_MS,
      max: RATE_LIMIT_MAX,
    },
    cors: {
      origins: corsOptions.origin,
      credentials: corsOptions.credentials,
    },
    bodySizeLimit: BODY_SIZE_LIMIT,
    // Never expose secrets or sensitive environment variables
  };

  res.json(safeConfig);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    timestamp: new Date().toISOString(),
    path: req.path,
    method: req.method,
  });

  const statusCode = err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(statusCode).json({
    error: 'Internal server error',
    message: isProduction ? undefined : err.message,
    requestId: req.id || Math.random().toString(36).substring(7),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// Start server
app.listen(PORT, () => {
  const env = process.env.NODE_ENV || 'development';
  console.log(`Server running on port ${PORT} (${env})`);

  // Log configuration in non-production
  if (env !== 'production') {
    console.log('Configuration:');
    console.log(`- CORS Origins: ${corsOptions.origin.join(', ')}`);
    console.log(`- Rate Limit: ${RATE_LIMIT_MAX} requests per ${RATE_LIMIT_WINDOW_MS / (60 * 1000)} minutes`);
    console.log(`- Body Size Limit: ${BODY_SIZE_LIMIT}`);
    console.log(`- Environment: ${env}`);
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully...');
  process.exit(0);
});

module.exports = app;

#!/usr/bin/env node

/**
 * Environment Variable Validation Script
 * Run this to check if your environment is properly configured
 */

const fs = require('fs');
const path = require('path');

// Required environment variables for different environments
const requiredEnvVars = {
  all: ['PORT', 'NODE_ENV'],
  production: [
    // 'DATABASE_URL',
    // 'JWT_SECRET', 
    // 'SESSION_SECRET',
  ],
  development: [],
  test: [],
};

// Recommended variables (warn if missing)
const recommendedEnvVars = {
  all: ['CORS_ORIGINS'],
  production: [
    'RATE_LIMIT_WINDOW_MS',
    'RATE_LIMIT_MAX',
    'BODY_SIZE_LIMIT',
  ],
  development: [],
  test: [],
};

// Validate environment variables
function validateEnvironment() {
  const env = process.env.NODE_ENV || 'development';
  console.log(`\n🔍 Validating environment: ${env}\n`);

  let hasErrors = false;
  let hasWarnings = false;

  // Check required variables
  const allRequired = [...requiredEnvVars.all, ...(requiredEnvVars[env] || [])];
  const missingRequired = allRequired.filter(varName => !process.env[varName]);

  if (missingRequired.length > 0) {
    hasErrors = true;
    console.log('❌ Missing REQUIRED environment variables:');
    missingRequired.forEach(varName => {
      console.log(`   - ${varName}`);
    });
  }

  // Check recommended variables
  const allRecommended = [...recommendedEnvVars.all, ...(recommendedEnvVars[env] || [])];
  const missingRecommended = allRecommended.filter(varName => !process.env[varName]);

  if (missingRecommended.length > 0) {
    hasWarnings = true;
    console.log('\n⚠️  Missing RECOMMENDED environment variables:');
    missingRecommended.forEach(varName => {
      console.log(`   - ${varName}`);
    });
  }

  // Security checks
  console.log('\n🔒 Security checks:');

  // Check for default/weak values in production
  if (env === 'production') {
    const securityChecks = [
      { var: 'JWT_SECRET', check: (val) => val && val.length >= 32, message: 'JWT secret should be at least 32 characters' },
      { var: 'SESSION_SECRET', check: (val) => val && val.length >= 32, message: 'Session secret should be at least 32 characters' },
      { var: 'CORS_ORIGINS', check: (val) => val && val.includes('localhost') === false, message: 'Avoid localhost in production CORS origins' },
      { var: 'DISABLE_CSP', check: (val) => val !== 'true', message: 'CSP should not be disabled in production' },
      { var: 'DISABLE_RATE_LIMIT', check: (val) => val !== 'true', message: 'Rate limiting should not be disabled in production' },
    ];

    securityChecks.forEach(check => {
      const value = process.env[check.var];
      if (value && !check.check(value)) {
        hasWarnings = true;
        console.log(`   ⚠️  ${check.var}: ${check.message}`);
      }
    });
  }

  // Check for development values in production
  if (env === 'production') {
    const devValues = [
      { var: 'PORT', value: '3000', message: 'Consider using standard port 80/443 in production' },
    ];

    devValues.forEach(check => {
      if (process.env[check.var] === check.value) {
        console.log(`   ℹ️  ${check.var}: ${check.message}`);
      }
    });
  }

  // Display current configuration (safe values only)
  console.log('\n📋 Current configuration:');
  const safeVars = [
    'PORT', 'NODE_ENV', 'CORS_ORIGINS', 'RATE_LIMIT_WINDOW_MS', 
    'RATE_LIMIT_MAX', 'BODY_SIZE_LIMIT', 'APP_VERSION',
  ];

  safeVars.forEach(varName => {
    if (process.env[varName]) {
      console.log(`   ${varName}=${process.env[varName]}`);
    }
  });

  // Summary
  console.log('\n' + '='.repeat(50));
  if (hasErrors) {
    console.log('❌ Validation FAILED - Missing required variables');
    process.exit(1);
  } else if (hasWarnings) {
    console.log('⚠️  Validation passed with warnings');
    console.log('   Please review the recommended variables');
  } else {
    console.log('✅ Validation PASSED');
  }

  // Load .env file if exists
  const envPath = path.join(__dirname, '.env');
  if (fs.existsSync(envPath)) {
    console.log(`\n📁 Using .env file: ${envPath}`);
  } else {
    console.log('\n📁 No .env file found');
    console.log('   Create one from .env.example');
  }

  console.log('\n');
}

// Run validation
if (require.main === module) {
  // Try to load dotenv if available
  try {
    require('dotenv').config();
  } catch (e) {
    // dotenv not installed, continue with system env vars
  }

  validateEnvironment();
}

module.exports = { validateEnvironment };

