// Express application with all configurable values in environment variables
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');

const app = express();

// Configuration from environment variables with defaults
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const RATE_LIMIT_WINDOW_MS = parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000; // 15 minutes default
const RATE_LIMIT_MAX_REQUESTS = parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100;
const BODY_SIZE_LIMIT = process.env.BODY_SIZE_LIMIT || '10kb';

// Parse CORS origins from environment variable (comma-separated list)
const ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',') 
  : (NODE_ENV === 'production' 
      ? [] // No origins allowed by default in production - must be set explicitly
      : ['http://localhost:3000', 'http://localhost:8080']);

// Parse CSP directives from environment if needed
const CSP_DIRECTIVES = {
  defaultSrc: ["'self'"],
  styleSrc: ["'self'", "'unsafe-inline'"],
  scriptSrc: ["'self'"],
  imgSrc: ["'self'", "data:", "https:"],
};

// Security Middleware Setup

// 1. Helmet.js for security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: CSP_DIRECTIVES,
  },
  hsts: {
    maxAge: parseInt(process.env.HSTS_MAX_AGE) || 31536000, // 1 year default
    includeSubDomains: process.env.HSTS_INCLUDE_SUBDOMAINS === 'true',
    preload: process.env.HSTS_PRELOAD === 'true'
  }
}));

// 2. CORS configuration from environment
app.use(cors({
  origin: ALLOWED_ORIGINS,
  credentials: process.env.CORS_CREDENTIALS === 'true',
  optionsSuccessStatus: parseInt(process.env.CORS_SUCCESS_STATUS) || 200
}));

// 3. Rate limiting from environment
const apiLimiter = rateLimit({
  windowMs: RATE_LIMIT_WINDOW_MS,
  max: RATE_LIMIT_MAX_REQUESTS,
  message: process.env.RATE_LIMIT_MESSAGE || 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(apiLimiter);

// 4. Compression for performance
app.use(compression());

// 5. Request logging (configurable format)
const LOG_FORMAT = process.env.LOG_FORMAT || (NODE_ENV === 'production' ? 'combined' : 'dev');
app.use(morgan(LOG_FORMAT));

// 6. Body parsing with configurable size limits
app.use(express.json({ limit: BODY_SIZE_LIMIT }));
app.use(express.urlencoded({ extended: true, limit: BODY_SIZE_LIMIT }));

// Configurable endpoints
const USERS_DATA = process.env.USERS_DATA 
  ? JSON.parse(process.env.USERS_DATA) 
  : [
      { id: 1, name: 'User1', email: 'user1@example.com' },
      { id: 2, name: 'User2', email: 'user2@example.com' }
    ];

// Health endpoint (public)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
    config: {
      port: PORT,
      rateLimit: {
        windowMs: RATE_LIMIT_WINDOW_MS,
        maxRequests: RATE_LIMIT_MAX_REQUESTS
      },
      bodySizeLimit: BODY_SIZE_LIMIT
    }
  });
});

// Users endpoint - configurable data
app.get('/users', (req, res) => {
  // In production, add authentication middleware here
  // Authentication check could also be toggled via environment
  if (process.env.REQUIRE_AUTHENTICATION === 'true') {
    // Authentication logic would go here
    return res.status(401).json({ error: 'Authentication required' });
  }

  // Return user data (could be filtered based on environment)
  const includeEmail = process.env.INCLUDE_USER_EMAIL === 'true';
  const users = USERS_DATA.map(user => {
    const response = { id: user.id, name: user.name };
    if (includeEmail) {
      response.email = user.email;
    }
    return response;
  });

  res.json(users);
});

// Configurable maintenance mode
if (process.env.MAINTENANCE_MODE === 'true') {
  app.use((req, res, next) => {
    res.status(503).json({ 
      error: 'Service temporarily unavailable for maintenance',
      estimatedRestoration: process.env.MAINTENANCE_ETA || 'Unknown'
    });
  });
}

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Configurable error detail exposure
  const showErrorDetails = process.env.SHOW_ERROR_DETAILS === 'true';
  const errorResponse = {
    error: NODE_ENV === 'production' && !showErrorDetails
      ? 'Something went wrong' 
      : err.message
  };

  res.status(err.status || 500).json(errorResponse);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Graceful shutdown handling
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  console.log(`Config: Rate limit ${RATE_LIMIT_MAX_REQUESTS} requests per ${RATE_LIMIT_WINDOW_MS/1000/60} minutes`);
  console.log(`CORS allowed origins: ${ALLOWED_ORIGINS.join(', ') || 'none'}`);
});

// Handle graceful shutdown with configurable timeout
const GRACEFUL_SHUTDOWN_TIMEOUT = parseInt(process.env.GRACEFUL_SHUTDOWN_TIMEOUT) || 10000;

const shutdown = (signal) => {
  console.log(`${signal} received, shutting down gracefully`);

  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after timeout
  setTimeout(() => {
    console.error('Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, GRACEFUL_SHUTDOWN_TIMEOUT);
};

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));

module.exports = app;

