const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

// Load centralized configuration
const config = require('./config.js');

const app = express();

// ========== SECURITY MIDDLEWARE ==========
if (config.get('security.enableSecurityHeaders')) {
  app.use(helmet());
}

if (config.get('security.enableCors')) {
  app.use(cors({
    origin: config.get('security.corsOrigin'),
    credentials: config.get('security.cookieSecure')
  }));
}

if (config.get('security.enableRateLimit')) {
  const limiter = rateLimit({
    windowMs: config.get('rateLimit.windowMs'),
    max: config.get('rateLimit.maxRequests'),
    skipSuccessfulRequests: config.get('rateLimit.skipSuccessfulRequests'),
    message: 'Too many requests from this IP, please try again later.'
  });
  app.use(config.get('server.apiBaseUrl'), limiter);
}

// ========== REQUEST PARSING ==========
app.use(express.json({ limit: config.get('limits.jsonSize') }));
app.use(express.urlencoded({ 
  extended: true, 
  limit: config.get('limits.urlEncodedSize') 
}));

// ========== ROUTES ==========
app.get('/health', (req, res) => {
  if (config.get('features.maintenanceMode')) {
    return res.status(503).json({
      status: 'maintenance',
      message: 'Service temporarily unavailable for maintenance'
    });
  }

  res.json({
    status: 'ok',
    app: config.get('server.appName'),
    environment: config.get('server.environment'),
    timestamp: new Date().toISOString()
  });
});

app.get('/users', (req, res) => {
  // In production, this would come from a database
  // For development/demo, we use mock data
  if (config.get('server.environment') === 'production') {
    // Production would query database
    res.json({ message: 'User data from database' });
  } else {
    // Development uses mock data
    res.json(config.get('mockData.users'));
  }
});

