app.use((err, req, res, next) => {
  const errorDetails = {
    message: err.message,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
    ...(config.get('server.environment') === 'development' && { stack: err.stack })
  };

  console.error(`Application Error:`, errorDetails);

  res.status(err.status || 500).json({
    error: 'Internal server error',
    ...(config.get('server.environment') === 'development' && { 
      details: err.message,
      path: req.path 
    })
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method
  });
});

// ========== SERVER STARTUP ==========
const server = app.listen(config.get('server.port'), () => {
  console.log('\n' + '='.repeat(50));
  console.log(`🚀 ${config.get('server.appName')}`);
  console.log('='.repeat(50));

  config.printSummary();

  console.log(`\n✅ Server running on port ${config.get('server.port')}`);
  console.log(`🔗 Health check: http://localhost:${config.get('server.port')}/health`);

  if (config.get('server.environment') === 'development') {
    console.log(`👤 Mock users: http://localhost:${config.get('server.port')}/users`);
  }

  console.log('\n' + '='.repeat(50));
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('\n🛑 SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  console.log('\n🛑 SIGINT received, shutting down gracefully...');
  server.close(() => {
    console.log('✅ Server closed');
    process.exit(0);
  });
});

module.exports = { app, config, server };

