/**
 * SECURE Express.js Application
 * 
 * This version includes multiple security improvements:
 * 1. Security headers via Helmet.js
 * 2. Rate limiting
 * 3. CORS configuration
 * 4. Input validation
 * 5. Secure error handling
 * 6. Body parsing limits
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
require('dotenv').config(); // Load environment variables

const app = express();
const PORT = process.env.PORT || 3000;

// ====================
// SECURITY MIDDLEWARE
// ====================

// 1. Security headers with Helmet.js
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", "data:", "https:"],
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS 
    ? process.env.ALLOWED_ORIGINS.split(',') 
    : ['http://localhost:3000'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Rate Limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per window
  message: {
    error: 'Too many requests from this IP, please try again after 15 minutes.'
  },
  standardHeaders: true,
  legacyHeaders: false,
});

// Apply rate limiting to API routes
app.use('/api/', apiLimiter);

// More restrictive limiter for auth routes
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: {
    error: 'Too many login attempts, please try again after 15 minutes.'
  }
});

// 4. Body parsing with size limits (prevents DoS via large payloads)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// ====================
// ROUTES WITH SECURITY
// ====================

// Health endpoint - minimal information disclosure
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    uptime: Math.floor(process.uptime()),
    timestamp: new Date().toISOString().split('T')[0] // Only date, no time
  });
});

// Secure users endpoint with validation
app.get('/api/users', 
  // Validation middleware
  [
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
    body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
  ],
  (req, res) => {
    // Check validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In production, add authentication check
    // if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

    // Example secure data
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'user'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'bob@example.com',
        role: 'user'
      },
    ];

    // Sanitize sensitive data before sending
    const safeUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      // Don't expose email in production without auth
      // email: user.email 
    }));

    res.json(safeUsers);
  }
);

// Example secure login endpoint
app.post('/api/login', 
  authLimiter, // Stricter rate limiting for auth
  [
    body('email').isEmail().normalizeEmail(),
    body('password').isLength({ min: 8 })
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In production: validate credentials, generate JWT, etc.
    res.json({ 
      message: 'Login endpoint - implement proper authentication',
      token: 'jwt-token-here' 
    });
  }
);

// ====================
// ERROR HANDLING
// ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource was not found'
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    ip: req.ip
  });

  // Don't expose stack traces in production
  const errorResponse = {
    error: 'Internal Server Error',
    message: 'Something went wrong. Please try again later.'
  };

  // Include more details in development
  if (process.env.NODE_ENV === 'development') {
    errorResponse.details = err.message;
    errorResponse.stack = err.stack;
  }

  res.status(err.status || 500).json(errorResponse);
});

// ====================
// SERVER SETUP
// ====================

// HTTPS redirect middleware (for production)
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.headers['x-forwarded-proto'] !== 'https') {
      return res.redirect(`https://${req.headers.host}${req.url}`);
    }
    next();
  });
}

// Start server
const server = app.listen(PORT, () => {
  console.log(`🚀 Secure server running on port ${PORT}`);
  console.log(`📝 Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`🔒 Security features enabled:`);
  console.log(`   - Helmet.js security headers`);
  console.log(`   - Rate limiting (100 requests/15min per IP)`);
  console.log(`   - CORS configured`);
  console.log(`   - Input validation`);
  console.log(`   - Body size limits (10kb)`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

